        stack.append(value)

    def builtin_dup():
        value = pop()
        push(value)
        push(value)

    def builtin_drop():
        pop()

    def builtin_swap():
        first = pop()
        second = pop()
        push(first)
        push(second)

    def builtin_over():
        if len(stack) < 2:
            raise StackUnderflowError("Insufficient number of items in stack")
        push(stack[-2])

    def builtin_sub():
