        minuend = pop()
        push(minuend - subtrahend)

    builtins = {
        "+": lambda: push(pop() + pop()),
        "-": builtin_sub,
        "*": lambda: push(pop() * pop()),
        "/": lambda: push(_trunc_div(pop(), pop())),
        "dup": builtin_dup,
        "drop": builtin_drop,
        "swap": builtin_swap,
        "over": builtin_over,
    }

    def execute(body):
        work = [(body, 0)]
        while work:
            current, index = work[-1]
